-- Fill the task dungeons out past the entrance.
--
-- The first population put twelve to fifteen creatures in each dungeon, all
-- of them within 1,500 units of the door and all along a single line. Walking
-- one shows the result plainly: a knot of monsters at the entrance and an
-- empty dungeon behind it. A task dungeon should be full the whole way in.
--
-- The reasoning is unchanged -- we have no geometry for these maps, only the
-- door and the way it faces -- but three things are different.
--
-- Depth. Creatures now run to 4,200 units in rather than stopping at 1,500,
-- so the length of the dungeon is used.
--
-- Branching. They are laid out along three arms: the corridor the entrance
-- faces, and one to either side of it. These dungeons bend, and with no map
-- three arms make it far likelier that a corridor has something standing on
-- it than a single straight line does.
--
-- Packs. Creatures of one kind stand together now, three to five at a time,
-- two packs to an arm and six in all, drawn round the dungeon's own list
-- of creatures so each kind gets at least one pack of its own. That is how a
-- dungeon reads, and it is what the tasks need: a "kill eight of these"
-- mission counts what actually spawned, so eight of that creature have to be
-- down there to begin with. Before this a kind might have had two, and the
-- task would have been over in a minute.
--
-- This migration owns the whole population rather than adding to migration
-- 68's. instancexelement has no PackageID to tag rows with, so a migration
-- that only added to what was already there could not be re-run safely.
-- Everything below, entrance knot included, is emitted here; the near rows
-- are migration 68's own, read out of that file unchanged, so the creature
-- mix and the boss chosen per dungeon are preserved -- a Gossamer Grotto is
-- still spiders.
--
-- Some of these will stand inside rock. That cannot be avoided without the
-- geometry, which is why the mission that counts them allows a margin rather
-- than demanding the very last kill -- see GaherisTaskDungeonMission.
--
-- Deterministic: seeded per dungeon, so regenerating gives the same layout.

DELETE FROM instancexelement WHERE ClassType <> 'entrance';

